using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;
public sealed class ProcessingPipeline(IChunker chunker){public DocumentProcessed Process(DocumentIngestionCompleted input,string text,int maxTokens,int overlapTokens,IReadOnlyList<Guid>? allowedPrincipalIds=null){if(input.TenantId==Guid.Empty)throw new ArgumentException("Tenant is required");if(input.DocumentId==Guid.Empty||input.VersionId==Guid.Empty)throw new ArgumentException("Document/version is required");var chunks=chunker.Chunk(text,maxTokens,overlapTokens);return new(Guid.NewGuid(),input.TenantId,input.DocumentId,input.VersionId,chunks,DateTimeOffset.UtcNow,input.CorrelationId,allowedPrincipalIds);}}